-- Generated by npm run generate. No existing tables are dropped.

CREATE TABLE HW_BRANCHES (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  name VARCHAR2(60 CHAR) NOT NULL UNIQUE CHECK (TRIM(name) IS NOT NULL AND LENGTH(TRIM(name)) = LENGTH(name)),
  city VARCHAR2(60 CHAR) NOT NULL CHECK (TRIM(city) IS NOT NULL AND LENGTH(TRIM(city)) = LENGTH(city))
);

CREATE TABLE HW_CUSTOMERS (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  name VARCHAR2(80 CHAR) NOT NULL CHECK (TRIM(name) IS NOT NULL AND LENGTH(TRIM(name)) = LENGTH(name)),
  email VARCHAR2(120 CHAR) NOT NULL UNIQUE CHECK (TRIM(email) IS NOT NULL AND LENGTH(TRIM(email)) = LENGTH(email))
);

CREATE TABLE HW_EMPLOYEES (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  branch_id NUMBER(10) NOT NULL REFERENCES HW_BRANCHES(id) CHECK (branch_id >= 1 AND branch_id <= 2147483647),
  name VARCHAR2(80 CHAR) NOT NULL CHECK (TRIM(name) IS NOT NULL AND LENGTH(TRIM(name)) = LENGTH(name)),
  role VARCHAR2(30 CHAR) NOT NULL CHECK (TRIM(role) IS NOT NULL AND LENGTH(TRIM(role)) = LENGTH(role) AND role IN ('TELLER', 'ADVISOR', 'MANAGER'))
);

CREATE TABLE HW_ACCOUNT_TYPES (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  name VARCHAR2(40 CHAR) NOT NULL UNIQUE CHECK (TRIM(name) IS NOT NULL AND LENGTH(TRIM(name)) = LENGTH(name)),
  monthly_fee NUMBER(12,2) NOT NULL CHECK (monthly_fee >= 0 AND monthly_fee <= 9999999999.99)
);

CREATE TABLE HW_ACCOUNTS (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  branch_id NUMBER(10) NOT NULL REFERENCES HW_BRANCHES(id) CHECK (branch_id >= 1 AND branch_id <= 2147483647),
  account_type_id NUMBER(10) NOT NULL REFERENCES HW_ACCOUNT_TYPES(id) CHECK (account_type_id >= 1 AND account_type_id <= 2147483647),
  account_number VARCHAR2(24 CHAR) NOT NULL UNIQUE CHECK (TRIM(account_number) IS NOT NULL AND LENGTH(TRIM(account_number)) = LENGTH(account_number)),
  balance NUMBER(12,2) NOT NULL CHECK (balance >= 0 AND balance <= 9999999999.99),
  opened_on DATE NOT NULL CHECK (opened_on = TRUNC(opened_on)),
  status VARCHAR2(10 CHAR) NOT NULL CHECK (TRIM(status) IS NOT NULL AND LENGTH(TRIM(status)) = LENGTH(status) AND status IN ('ACTIVE', 'CLOSED'))
);

CREATE TABLE HW_ACCOUNT_HOLDERS (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  account_id NUMBER(10) NOT NULL REFERENCES HW_ACCOUNTS(id) CHECK (account_id >= 1 AND account_id <= 2147483647),
  customer_id NUMBER(10) NOT NULL REFERENCES HW_CUSTOMERS(id) CHECK (customer_id >= 1 AND customer_id <= 2147483647),
  holder_role VARCHAR2(10 CHAR) NOT NULL CHECK (TRIM(holder_role) IS NOT NULL AND LENGTH(TRIM(holder_role)) = LENGTH(holder_role) AND holder_role IN ('PRIMARY', 'JOINT')),
  UNIQUE (account_id, customer_id)
);

CREATE TABLE HW_TRANSACTIONS (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  account_id NUMBER(10) NOT NULL REFERENCES HW_ACCOUNTS(id) CHECK (account_id >= 1 AND account_id <= 2147483647),
  employee_id NUMBER(10) REFERENCES HW_EMPLOYEES(id) CHECK (employee_id >= 1 AND employee_id <= 2147483647),
  kind VARCHAR2(10 CHAR) NOT NULL CHECK (TRIM(kind) IS NOT NULL AND LENGTH(TRIM(kind)) = LENGTH(kind) AND kind IN ('DEPOSIT', 'WITHDRAWAL')),
  amount NUMBER(12,2) NOT NULL CHECK (amount > 0 AND amount <= 9999999999.99),
  occurred_on DATE NOT NULL CHECK (occurred_on = TRUNC(occurred_on))
);

CREATE TABLE HW_LOAN_TYPES (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  name VARCHAR2(40 CHAR) NOT NULL UNIQUE CHECK (TRIM(name) IS NOT NULL AND LENGTH(TRIM(name)) = LENGTH(name)),
  annual_rate NUMBER(12,2) NOT NULL CHECK (annual_rate >= 0 AND annual_rate <= 100)
);

CREATE TABLE HW_LOANS (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  customer_id NUMBER(10) NOT NULL REFERENCES HW_CUSTOMERS(id) CHECK (customer_id >= 1 AND customer_id <= 2147483647),
  branch_id NUMBER(10) NOT NULL REFERENCES HW_BRANCHES(id) CHECK (branch_id >= 1 AND branch_id <= 2147483647),
  loan_type_id NUMBER(10) NOT NULL REFERENCES HW_LOAN_TYPES(id) CHECK (loan_type_id >= 1 AND loan_type_id <= 2147483647),
  employee_id NUMBER(10) NOT NULL REFERENCES HW_EMPLOYEES(id) CHECK (employee_id >= 1 AND employee_id <= 2147483647),
  principal NUMBER(12,2) NOT NULL CHECK (principal > 0 AND principal <= 9999999999.99),
  issued_on DATE NOT NULL CHECK (issued_on = TRUNC(issued_on)),
  status VARCHAR2(10 CHAR) NOT NULL CHECK (TRIM(status) IS NOT NULL AND LENGTH(TRIM(status)) = LENGTH(status) AND status IN ('ACTIVE', 'PAID'))
);

CREATE TABLE HW_LOAN_PAYMENTS (
  id NUMBER(10) PRIMARY KEY CHECK (id >= 1 AND id <= 2147483647),
  loan_id NUMBER(10) NOT NULL REFERENCES HW_LOANS(id) CHECK (loan_id >= 1 AND loan_id <= 2147483647),
  account_id NUMBER(10) NOT NULL REFERENCES HW_ACCOUNTS(id) CHECK (account_id >= 1 AND account_id <= 2147483647),
  amount NUMBER(12,2) NOT NULL CHECK (amount > 0 AND amount <= 9999999999.99),
  paid_on DATE NOT NULL CHECK (paid_on = TRUNC(paid_on))
);
